style.css:
@-moz-document domain("youtube.com") {
/* Hide the default YouTube logo */
    #logo-icon,
    ytd-topbar-logo-renderer svg {
        display: none !important;
    }

    /* Replace with your image */
    ytd-topbar-logo-renderer a#logo {
        display: flex !important;
        align-items: center;
        justify-content: center;
        width: 140px !important;
        height: 56px !important;
        background: url("https://i.pinimg.com/1200x/c9/19/17/c91917e72c3b0cd36b04ae9bfc6fa715.jpg") center center / contain no-repeat !important;
    }

    /* Remove any leftover text */
    ytd-topbar-logo-renderer #country-code {
        display: none !important;
    }
}
